<?php

declare(strict_types=1);

namespace Zero\Wp;

/**
 * Applies zero/app/migrations/NNNN_<name>.sql (MySQL dialect, generated by `zero build`) in
 * filename order, recorded in {prefix}zero__migrations keyed by (app, id): ids like `0001_init`
 * repeat across apps, so each app sees only its own rows (see `ledger` for converting an old one). `{prefix}` in the SQL is replaced by
 * $wpdb->prefix. MySQL DDL commits implicitly, so each statement that succeeds is recorded as
 * `<id>:<n>` and skipped on the retry; the file's own id is recorded (and the progress rows removed)
 * once every statement has run. A file that failed half way therefore resumes where it stopped.
 *
 * A statement can commit without its marker (the process died between the two). The retry then
 * fails on it ("already exists") and keeps failing, by design: nothing guesses that the existing
 * object is the right one. The operator checks it and records the step with
 * `wp zero migrate --mark-applied <id>:<n>` (see `markApplied`); the next request resumes after it.
 *
 * After migrating, every Zero table plus wp_posts/wp_postmeta must be InnoDB: Zero's request
 * transactions depend on it (§3.3), so every migration path refuses otherwise.
 */
final class Migrator
{

    public function __construct(private readonly Connection $db, private readonly string $dir, private readonly \Zero\Schema $schema)
    {
    }

    /** The statements of a migration file: split on the compiler's `--> statement-breakpoint` lines. */
    public static function statements(string $sql): array
    {
        $parts = preg_split('/-->[ \t]*statement-breakpoint/', $sql) ?: [];

        return array_values(array_filter(array_map('trim', $parts), static fn ($s) => $s !== ''));
    }

    /**
     * Records `<id>:<n>` (statement n of migration id) as applied without running it, for a statement
     * whose effect is already in the database. Only the next pending statement can be marked.
     */
    public function markApplied(string $step): void
    {
        if (!preg_match('/^(.+):([1-9]\\d*)$/', $step, $m)) {
            throw \Zero\HttpError::invalidInput('--mark-applied takes <migration id>:<statement number>, e.g. 0002_update:1', '/mark-applied');
        }
        [, $id, $n] = $m;
        // Only a migration file of this app, named exactly as `pending()` names it (no paths).
        $files = array_map(static fn (string $f): string => basename($f, '.sql'), glob($this->dir . '/*.sql') ?: []);
        if (!in_array($id, $files, true)) {
            throw new \Zero\HttpError(409, 'not_pending', "$id is not a pending migration of this app");
        }
        $file = $this->dir . '/' . $id . '.sql';
        $ledger = $this->ledger();
        $done = array_flip($this->done());
        if (!is_file($file) || isset($done[$id])) {
            throw new \Zero\HttpError(409, 'not_pending', "$id is not a pending migration of this app");
        }
        $count = count(self::statements((string) file_get_contents($file)));
        $next = 1;
        while (isset($done["$id:$next"])) {
            $next++;
        }
        if ((int) $n !== $next || $next > $count) {
            throw new \Zero\HttpError(409, 'not_pending', "the next pending statement of $id is $next of $count; only that one can be marked");
        }
        $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`) VALUES (?, ?, ?)", [$this->schema->name(), $step, gmdate('Y-m-d\\TH:i:s.000\\Z')]);
    }

    /** @return list<string> ids applied by this call */
    public function migrate(): array
    {
        $this->requireCompatibleTables();
        $app = $this->schema->name();
        $files = glob($this->dir . '/*.sql') ?: [];
        sort($files, SORT_STRING);
        $migrations = [];
        foreach ($files as $file) {
            $id = basename($file, '.sql');
            $sql = str_replace('{prefix}', $this->db->prefix(), (string) file_get_contents($file));
            $migrations[$id] = self::statements($sql);
        }
        // Check every pending adoption before any DDL or ledger writes, even across tables/files.
        $done = $this->keyed() ? array_flip($this->done()) : [];
        foreach ($migrations as $id => $statements) {
            if (isset($done[$id])) {
                continue;
            }
            foreach ($statements as $i => $statement) {
                if (!str_starts_with($statement, '-- zero-adopt ') || isset($done[$id . ':' . ($i + 1)])) {
                    continue;
                }
                try {
                    $this->validateAdoption($statement);
                    $this->db->run($statement);
                } catch (DbError $e) {
                    throw new \RuntimeException("Migration $id failed at statement " . ($i + 1) . ': ' . $e->getMessage(), 0, $e);
                }
            }
        }
        $ledger = $this->ledger();
        $done = array_flip($this->done());
        $applied = [];
        foreach ($migrations as $id => $statements) {
            if (isset($done[$id])) {
                continue;
            }
            foreach ($statements as $i => $statement) {
                $step = $id . ':' . ($i + 1);
                if (isset($done[$step])) {
                    continue;
                }
                try {
                    $this->db->run($statement);
                } catch (DbError $e) {
                    throw new \RuntimeException("Migration $id failed at statement " . ($i + 1) . ': ' . $e->getMessage(), 0, $e);
                }
                $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`) VALUES (?, ?, ?)", [$app, $step, gmdate('Y-m-d\TH:i:s.000\Z')]);
            }
            $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`) VALUES (?, ?, ?)", [$app, $id, gmdate('Y-m-d\TH:i:s.000\Z')]);
            $this->db->run("DELETE FROM `$ledger` WHERE `app` = ? AND `id` LIKE ?", [$app, $this->db->wpdb()->esc_like($id . ':') . '%']);
            $applied[] = $id;
        }

        $this->requireCompatibleTables();
        return $applied;
    }

    private function requireCompatibleTables(): void
    {
        $bad = $this->nonInnoDb();
        if ($bad !== []) {
            throw new \RuntimeException('Zero needs InnoDB tables with utf8mb4; these are incompatible: ' . implode(', ', $bad));
        }
    }

    /** Adoption records compiler names in the snapshot; verify those names before recording the step. */
    private function validateAdoption(string $statement): void
    {
        if (!str_starts_with($statement, '-- zero-adopt ')) {
            return;
        }
        $expected = json_decode(explode("\n", substr($statement, strlen('-- zero-adopt ')), 2)[0], true, flags: JSON_THROW_ON_ERROR);
        $table = $expected['table'];
        $indexes = [];
        foreach ($this->db->run('SELECT INDEX_NAME AS n, NON_UNIQUE AS u, COLUMN_NAME AS c, SUB_PART AS p FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? ORDER BY INDEX_NAME, SEQ_IN_INDEX', [$table]) as $row) {
            $indexes[$row['n']][] = $row;
        }
        foreach ($expected['indexes'] as $index) {
            $actual = $indexes[$index['name']] ?? [];
            if (array_column($actual, 'c') !== $index['columns']
                || array_filter($actual, static fn (array $r): bool => (int) $r['u'] !== (int) !$index['unique'] || $r['p'] !== null) !== []) {
                throw new DbError("Cannot adopt $table: index {$index['name']} must already have the declared columns and uniqueness, without prefix lengths");
            }
        }
        // Later foreign keys use the schema's BIGINT signedness; never guess the adopted key's type.
        $columns = array_column($this->db->run('SELECT COLUMN_NAME AS n, DATA_TYPE AS t, COLUMN_TYPE AS c FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', [$table]), null, 'n');
        foreach ($expected['integerColumns'] ?? [] as $column) {
            $actual = $columns[$column['name']] ?? null;
            $type = $column['unsigned'] ? 'BIGINT UNSIGNED' : 'BIGINT';
            if ($actual === null || strtolower($actual['t']) !== 'bigint'
                || str_contains(strtolower($actual['c']), 'unsigned') !== $column['unsigned']) {
                throw new DbError("Cannot adopt $table: column {$column['name']} must use $type");
            }
        }
        foreach ($expected['foreignKeys'] as $key) {
            $actual = $this->db->run('SELECT k.COLUMN_NAME AS c, k.REFERENCED_TABLE_NAME AS t, k.REFERENCED_COLUMN_NAME AS r, r.DELETE_RULE AS d, r.UPDATE_RULE AS u FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME WHERE k.CONSTRAINT_SCHEMA = DATABASE() AND k.REFERENCED_TABLE_SCHEMA = DATABASE() AND k.TABLE_NAME = ? AND k.CONSTRAINT_NAME = ? ORDER BY k.ORDINAL_POSITION', [$table, $key['name']]);
            $rule = static fn (string $value): string => $value === 'NO ACTION' ? 'RESTRICT' : $value;
            if (count($actual) !== 1 || $actual[0]['c'] !== $key['column'] || $actual[0]['t'] !== $key['table'] || $actual[0]['r'] !== $key['target']
                || $rule($actual[0]['d']) !== $rule($key['onDelete']) || $rule($actual[0]['u']) !== $rule($key['onUpdate'])) {
                throw new DbError("Cannot adopt $table: foreign key {$key['name']} must already have the declared target and actions");
            }
        }
    }

    /**
     * Runs $fn holding a MySQL named lock scoped to this site's database and table prefix, so every
     * writer (first request, activation, `wp zero migrate`) applies a given migration once. Waits up
     * to 30 seconds for another holder, then throws rather than letting the caller run on a schema
     * that is still changing.
     */
    public static function locked(Connection $db, string $name, callable $fn): mixed
    {
        return $db->locked('zero:' . substr(hash('sha256', DB_NAME . ':' . $db->prefix() . ':' . $name), 0, 40), 30, $fn);
    }

    /**
     * Brings storage up to date on a request that found it stale: runs $fn under the lock unless
     * $current() turns true once the lock is held (another request finished first). Returns null
     * when storage is current, or the problem when it isn't: the caller keeps WordPress serving,
     * refuses Zero operations, logs, and tells administrators; the next request retries.
     *
     * @param callable(): bool $current
     */
    public static function upgrade(Connection $db, string $name, callable $current, callable $fn): ?string
    {
        try {
            self::locked($db, $name, static function () use ($current, $fn): void {
                if (!$current()) {
                    $fn();
                }
            });

            return null;
        } catch (\Throwable $e) {
            $problem = $e->getMessage();
            error_log('[zero] ' . $problem);
            add_action('admin_notices', static function () use ($problem): void {
                if (current_user_can('manage_options')) {
                    printf('<div class="notice notice-error"><p>%s</p></div>', esc_html('Zero: ' . $problem));
                }
            });

            return $problem;
        }
    }

    /**
     * The ledger table, created on first use. Rows carry the app's name (`app`, up to the 191
     * characters an index allows; `zero build` names are plugin slugs well under that).
     *
     * A ledger from before rows were keyed by app belongs to the one app that ran on the site: its
     * rows go to the app whose `zero_<app>_schema` option exists. With no such app, or several, the
     * owner is unknown and the conversion refuses instead of guessing: replaying another app's
     * history could drop data. Creation and conversion hold one site-wide lock (every app shares the
     * table, so two apps' locks wouldn't serialize them) and re-check after acquiring it.
     */
    public function ledger(): string
    {
        $ledger = $this->table('zero__migrations');
        if ($this->keyed()) {
            return $ledger;
        }
        self::locked($this->db, 'zero__migrations', fn () => $this->createOrConvert($ledger));

        return $ledger;
    }

    private function createOrConvert(string $ledger): void
    {
        $exists = $this->db->run('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', [$ledger]) !== [];
        if (!$exists) {
            $this->db->run("CREATE TABLE `$ledger` (`app` VARCHAR(191) NOT NULL, `id` VARCHAR(191) NOT NULL, `applied_at` CHAR(24) NOT NULL, PRIMARY KEY (`app`, `id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        } elseif (!$this->keyed()) {
            $owners = $this->legacyOwners();
            if (count($owners) !== 1) {
                throw new \RuntimeException('the migration ledger predates per-app keys and its owner is unclear (' . ($owners === [] ? 'no app' : implode(', ', $owners)) . "); set its rows' app with: ALTER TABLE `$ledger` ADD COLUMN `app` VARCHAR(191) NOT NULL DEFAULT '<app>' FIRST, DROP PRIMARY KEY, ADD PRIMARY KEY (`app`, `id`)");
            }
            $this->db->run("ALTER TABLE `$ledger` ADD COLUMN `app` VARCHAR(191) NOT NULL DEFAULT '" . esc_sql($owners[0]) . "' FIRST, DROP PRIMARY KEY, ADD PRIMARY KEY (`app`, `id`)");
            $this->db->run("ALTER TABLE `$ledger` ALTER COLUMN `app` DROP DEFAULT");
        }
    }

    /** Whether the ledger exists and is keyed by app (false for a missing or pre-key ledger). */
    public function keyed(): bool
    {
        return $this->db->run('SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?', [$this->table('zero__migrations'), 'app']) !== [];
    }

    /** @return list<string> apps with a recorded schema hash on this site */
    private function legacyOwners(): array
    {
        $options = $this->db->wpdb()->options;
        $owners = [];
        foreach ($this->db->run("SELECT `option_name` AS n FROM `$options` WHERE `option_name` LIKE 'zero\\_%\\_schema'") as $row) {
            if (preg_match('/^zero_(.+)_schema$/', (string) $row['n'], $m)) {
                $owners[] = $m[1];
            }
        }

        return $owners;
    }

    /** @return list<string> this app's recorded ids (files and in-progress `<id>:<n>` steps) */
    private function done(): array
    {
        return array_column($this->db->run('SELECT `id` FROM `' . $this->table('zero__migrations') . '` WHERE `app` = ?', [$this->schema->name()]), 'id');
    }

    public function pending(): array
    {
        $done = $this->keyed() ? $this->done() : [];
        $files = array_map(static fn (string $file): string => basename($file, '.sql'), glob($this->dir . '/*.sql') ?: []);
        sort($files, SORT_STRING);
        return array_values(array_diff($files, $done));
    }

    /**
     * Tables that must be InnoDB but aren't: core posts/postmeta and every `{prefix}zero_*` table.
     *
     * @return list<string>
     */
    public function nonInnoDb(): array
    {
        $wpdb = $this->db->wpdb();
        // Users join Zero's transactions too (auth collections and guests, §6.2): check them always.
        $names = [$wpdb->posts, $wpdb->postmeta, $wpdb->users, $wpdb->usermeta];
        foreach ($this->schema->collections() as $spec) {
            if (isset($spec['existingTable'])) {
                $names[] = $spec['existingTable'];
            }
        }
        $placeholders = implode(', ', array_fill(0, count($names), '?'));
        $rows = $this->db->run(
            'SELECT TABLE_NAME AS t, ENGINE AS e, TABLE_COLLATION AS c FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND (TABLE_NAME IN (' . $placeholders . ') OR TABLE_NAME LIKE ?)',
            [...$names, $wpdb->esc_like($this->db->prefix() . 'zero_') . '%'],
        );
        $bad = [];
        foreach ($rows as $r) {
            if (strcasecmp((string) $r['e'], 'InnoDB') !== 0 || !str_starts_with(strtolower((string) $r['c']), 'utf8mb4_')) {
                $bad[] = (string) $r['t'];
            }
        }

        return $bad;
    }

    private function table(string $name): string
    {
        return $this->db->prefix() . $name;
    }
}
